insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-03','en-a1-03',null,1,3,'published',1,'{"id":"en-a1-03","baseId":"en-a1-03","revision":1,"level":"A1","levelIndex":1,"order":3,"title":"To be: inkor, savol va qisqa javob","objective":"Ma’lumotni tekshirasiz, inkor qilasiz va qisqa javob berasiz.","context":"Sinfdoshlar qaysi xona dars uchun to‘g‘ri ekanini aniqlaydi.","prerequisites":["en-a1-02"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas.","Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi.","Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi."],"pattern":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","examples":["Are you ready?","Yes, I am.","Is this our classroom?","No, it isn’t.","We are not late.","Ali isn’t in the library."],"vocabulary":[{"id":"en-a1-03-v0","term":"late","meaning":"kechikkan","ipa":"/leɪt/","collocation":"be late","example":"We are not late."},{"id":"en-a1-03-v1","term":"classroom","meaning":"sinfxona","ipa":"/ˈklɑːsruːm/","collocation":"our classroom","example":"Is this our classroom?"},{"id":"en-a1-03-v2","term":"quiet","meaning":"sokin","ipa":"/ˈkwaɪət/","collocation":"a quiet room","example":"a quiet room"},{"id":"en-a1-03-v3","term":"right","meaning":"to‘g‘ri","ipa":"/raɪt/","collocation":"the right room","example":"the right room"}],"visuals":[{"kind":"dialogue","title":"Ma’no va tuzilish","items":["She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","Are you ready?","Yes, I am."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinfdoshlar qaysi xona dars uchun to‘g‘ri ekanini aniqlaydi.","Is this our classroom?","We are not late."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"No, it isn’t.","audio":"/english-course/v7.23/en-a1-03-dictation.mp3"},"exercises":[{"id":"en-a1-03-choice","type":"choice","skill":"grammar","prompt":"Are you a student? savoliga qisqa javob tanlang.","answers":["Yes, I am."],"explanation":"Tasdiq qisqa javobda am to‘liq shaklda keladi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["Yes, I am.","Yes, I’m.","Yes, I is."]},{"id":"en-a1-03-gap","type":"grammarFill","skill":"grammar","prompt":"___ she ready?","answers":["Is"],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t."},{"id":"en-a1-03-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Are you ready?"],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","tokens":["Are","you","ready?"]},{"id":"en-a1-03-fix","type":"correction","skill":"grammar","prompt":"Do you are ready?","answers":["Are you ready?"],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t."},{"id":"en-a1-03-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["kechikkan","sinfxona","sokin","to‘g‘ri"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","left":["late","classroom","quiet","right"],"options":["kechikkan","sinfxona","sokin","to‘g‘ri"]},{"id":"en-a1-03-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["late","classroom","quiet","right"],"options":["be late","our classroom","a quiet room","the right room"],"answers":["be late","our classroom","a quiet room","the right room"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"To be: inkor, savol va qisqa javob — vaziyat","text":"Ali and Lola are outside Room 4. Ali asks, “Is this our classroom?” Lola looks at the timetable. “No, it isn’t. Our lesson is in Room 5.” They are not late. Room 5 is next to the library. The teacher asks, “Are you ready?” The students say, “Yes, we are.” They open their books and begin the lesson.","sentences":["Ali and Lola are outside Room 4.","Ali asks, “Is this our classroom?","” Lola looks at the timetable.","“No, it isn’t.","Our lesson is in Room 5.","” They are not late.","Room 5 is next to the library.","The teacher asks, “Are you ready?","” The students say, “Yes, we are.","” They open their books and begin the lesson."],"questions":[{"id":"en-a1-03-reading0","type":"choice","skill":"reading","prompt":"To‘g‘ri xona qaysi?","answers":["Room 5"],"explanation":"Lola jadvalni tekshirib Room 5 deydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["Room 5","Room 4","the library"]},{"id":"en-a1-03-reading1","type":"choice","skill":"reading","prompt":"O‘quvchilar kechikdimi?","answers":["No"],"explanation":"They are not late — inkor.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["No","Yes","The text does not say"]},{"id":"en-a1-03-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["Ali and Lola are outside Room 4.","Ali asks, “Is this our classroom?","” Lola looks at the timetable.","“No, it isn’t.","Our lesson is in Room 5.","” They are not late.","Room 5 is next to the library.","The teacher asks, “Are you ready?","” The students say, “Yes, we are.","” They open their books and begin the lesson."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Is this Room 5? Yes, it is. Is Ali here? No, he isn’t. Lola is here, and she is ready. We are not late. The lesson starts now.","audio":"/english-course/v7.23/en-a1-03.mp3","synthetic":true,"questions":[{"id":"en-a1-03-listening0","type":"choice","skill":"listening","prompt":"Ali xonadami?","answers":["No"],"explanation":"No, he isn’t — Ali haqida inkor.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["No","Yes","Only at night"]},{"id":"en-a1-03-listening1","type":"choice","skill":"listening","prompt":"Kim tayyor?","answers":["Lola"],"explanation":"Lola is ready deyiladi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["Lola","Ali","Vali"]},{"id":"en-a1-03-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["5","Lola"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","rows":["Xona","Tayyor o‘quvchi"]},{"id":"en-a1-03-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["No, it isn’t."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","audio":"/english-course/v7.23/en-a1-03-dictation.mp3","transcript":"No, it isn’t."}]},"writing":{"task":"Yangi sinfdosh uchun ikki savol va ularga qisqa javob yozing. Bitta noto‘g‘ri ma’lumotni inkor qiling.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"Is this our classroom? Yes, it is. Are we late? No, we aren’t. Our teacher is here. Ali is not here yet, but his bag is on the desk. We are ready for the lesson.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["Are you ready?","Yes, I am.","Is this our classroom?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Joy va holat haqida uchta savol bering. Sherigingiz qisqa javob bersin.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Yangi sinfdosh uchun ikki savol va ularga qisqa javob yozing. Bitta noto‘g‘ri ma’lumotni inkor qiling.","exit":[[{"id":"en-a1-03-exit0","type":"grammarFill","skill":"grammar","prompt":"Is he late? No, he ___.","answers":["isn’t"],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t."},{"id":"en-a1-03-exit1","type":"grammarFill","skill":"grammar","prompt":"___ they at school?","answers":["Are"],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t."},{"id":"en-a1-03-exit2","type":"grammarFill","skill":"grammar","prompt":"I am ___ late.","answers":["not"],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t."},{"id":"en-a1-03-exit3","type":"choice","skill":"grammar","prompt":"To be bilan to‘g‘ri savol qaysi?","answers":["Is Lola here?"],"explanation":"Is egadan oldin keladi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["Is Lola here?","Does Lola is here?","Lola is here? does"]},{"id":"en-a1-03-exit4","type":"choice","skill":"grammar","prompt":"Are not qisqartmasi nima?","answers":["aren’t"],"explanation":"Are not → aren’t.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["aren’t","isn’t","don’t"]}],[{"id":"en-a1-03-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Yes, I am."],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","tokens":["Yes,","I","am."]},{"id":"en-a1-03-exit-b1","type":"grammarFill","skill":"grammar","prompt":"___ they at school?","answers":["Are"],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t."},{"id":"en-a1-03-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["No, it isn’t."],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","tokens":["No,","it","isn’t."]},{"id":"en-a1-03-exit-b3","type":"choice","skill":"grammar","prompt":"To be bilan to‘g‘ri savol qaysi?","answers":["Is Lola here?"],"explanation":"Is egadan oldin keladi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["Is Lola here?","Does Lola is here?","Lola is here? does"]},{"id":"en-a1-03-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Ali isn’t in the library."],"explanation":"Inkor uchun am/is/are dan keyin not keladi: I am not late. Is not → isn’t, are not → aren’t. Amn’t standart o‘quv shakli emas. Savolda fe’l egadan oldinga chiqadi: Are you ready? To be savoliga do/does qo‘shilmaydi. Qisqa javob egani va mos fe’lni saqlaydi: Yes, I am. No, she isn’t. Yes, I’m shakli yolg‘iz qisqa javob sifatida ishlatilmaydi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","tokens":["Ali","isn’t","in","the","library."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-a1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-a1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-a1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-a1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-a1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-speak","name":"British Council — Speaking (A1–B2)","levels":["A1","A2","B1","B2"],"skill":"speaking","url":"https://learnenglish.britishcouncil.org/free-resources/speaking","task":"Darajangizdagi video vaziyatidan ikki iborani o‘z dialogingizda ishlating.","lesson":"en-a1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-a1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-a1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-04','en-a1-04',null,1,4,'published',1,'{"id":"en-a1-04","baseId":"en-a1-04","revision":1,"level":"A1","levelIndex":1,"order":4,"title":"A, an va the: narsa haqida gapirish","objective":"Bir narsani birinchi va takroriy tilga olishni farqlaysiz.","context":"Lola kutubxonadan bir kitob topib, keyin shu kitobni tasvirlaydi.","prerequisites":["en-a1-03"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["A yoki an birinchi marta tilga olingan, bitta sanaladigan narsadan oldin keladi: a book, an apple.","A/an tanlovi harfga emas, keyingi tovushga bog‘liq: an hour, a university. Bu misollarda h talaffuz qilinmaydi, university /j/ bilan boshlanadi.","The suhbatdoshga ma’lum yoki aniqlangan narsani bildiradi. Bir kitobni aytdik; keyingi gapda the book deb aynan uni nazarda tutamiz."],"pattern":"I have a book. The book is about animals. / an apple, a university","examples":["I have a book.","The book is about animals.","She eats an apple.","He is a university student.","The library is near our school.","It is an interesting story."],"vocabulary":[{"id":"en-a1-04-v0","term":"apple","meaning":"olma","ipa":"/ˈæpl/","collocation":"an apple","example":"She eats an apple."},{"id":"en-a1-04-v1","term":"animal","meaning":"hayvon","ipa":"/ˈænɪməl/","collocation":"a wild animal","example":"The book is about animals."},{"id":"en-a1-04-v2","term":"interesting","meaning":"qiziqarli","ipa":"/ˈɪntrəstɪŋ/","collocation":"an interesting story","example":"It is an interesting story."},{"id":"en-a1-04-v3","term":"university","meaning":"universitet","ipa":"/ˌjuːnɪˈvɜːsəti/","collocation":"a university student","example":"He is a university student."}],"visuals":[{"kind":"object","title":"Ma’no va tuzilish","items":["I have a book. The book is about animals. / an apple, a university","I have a book.","The book is about animals."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Lola kutubxonadan bir kitob topib, keyin shu kitobni tasvirlaydi.","She eats an apple.","The library is near our school."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"He is a university student.","audio":"/english-course/v7.23/en-a1-04-dictation.mp3"},"exercises":[{"id":"en-a1-04-choice","type":"choice","skill":"grammar","prompt":"Birinchi marta bitta kitob haqida gapiring.","answers":["I have a book."],"explanation":"Book undosh tovush bilan boshlanadi.","hint":"I have a book. The book is about animals. / an apple, a university","options":["I have a book.","I have an book.","I have book a."]},{"id":"en-a1-04-gap","type":"grammarFill","skill":"grammar","prompt":"She eats ___ apple.","answers":["an"],"explanation":"A yoki an birinchi marta tilga olingan, bitta sanaladigan narsadan oldin keladi: a book, an apple. A/an tanlovi harfga emas, keyingi tovushga bog‘liq: an hour, a university. Bu misollarda h talaffuz qilinmaydi, university /j/ bilan boshlanadi. The suhbatdoshga ma’lum yoki aniqlangan narsani bildiradi. Bir kitobni aytdik; keyingi gapda the book deb aynan uni nazarda tutamiz.","hint":"I have a book. The book is about animals. / an apple, a university"},{"id":"en-a1-04-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I have a book."],"explanation":"A yoki an birinchi marta tilga olingan, bitta sanaladigan narsadan oldin keladi: a book, an apple. A/an tanlovi harfga emas, keyingi tovushga bog‘liq: an hour, a university. Bu misollarda h talaffuz qilinmaydi, university /j/ bilan boshlanadi. The suhbatdoshga ma’lum yoki aniqlangan narsani bildiradi. Bir kitobni aytdik; keyingi gapda the book deb aynan uni nazarda tutamiz.","hint":"I have a book. The book is about animals. / an apple, a university","tokens":["I","have","a","book."]},{"id":"en-a1-04-fix","type":"correction","skill":"grammar","prompt":"He is an university student.","answers":["He is a university student."],"explanation":"A yoki an birinchi marta tilga olingan, bitta sanaladigan narsadan oldin keladi: a book, an apple. A/an tanlovi harfga emas, keyingi tovushga bog‘liq: an hour, a university. Bu misollarda h talaffuz qilinmaydi, university /j/ bilan boshlanadi. The suhbatdoshga ma’lum yoki aniqlangan narsani bildiradi. Bir kitobni aytdik; keyingi gapda the book deb aynan uni nazarda tutamiz.","hint":"I have a book. The book is about animals. / an apple, a university"},{"id":"en-a1-04-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["olma","hayvon","qiziqarli","universitet"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"I have a book. The book is about animals. / an apple, a university","left":["apple","animal","interesting","university"],"options":["olma","hayvon","qiziqarli","universitet"]},{"id":"en-a1-04-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["I have a book."],"tokens":["I","have","a","book."],"hint":"I have a book. The book is about animals. / an apple, a university","explanation":"A yoki an birinchi marta tilga olingan, bitta sanaladigan narsadan oldin keladi: a book, an apple."},{"id":"en-a1-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Kim haqida gapiryapmiz? Olmoshlar: Lola likes books. ___ reads every day.","answers":["She"],"explanation":"Fe’ldan oldin ega olmoshi she kerak.","hint":"Lola → she; Ali → he; Ali helps Lola → He helps her.","options":["She","Her","Him"],"recap":true,"sourceLesson":"Kim haqida gapiryapmiz? Olmoshlar"},{"id":"en-a1-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · To be: ism, kasb va holat: I ___ ready.","answers":["am"],"explanation":"I uchun am ishlatiladi.","hint":"I am / he, she, it is / you, we, they are","options":["am","is","are"],"recap":true,"sourceLesson":"To be: ism, kasb va holat"},{"id":"en-a1-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · To be: inkor, savol va qisqa javob: Are you a student? savoliga qisqa javob tanlang.","answers":["Yes, I am."],"explanation":"Tasdiq qisqa javobda am to‘liq shaklda keladi.","hint":"She is ready. → Is she ready? → Yes, she is. / No, she isn’t.","options":["Yes, I am.","Yes, I’m.","Yes, I is."],"recap":true,"sourceLesson":"To be: inkor, savol va qisqa javob"}],"reading":{"title":"A, an va the: narsa haqida gapirish — vaziyat","text":"Lola finds a book in the library. The book is about animals in Uzbekistan. There is an interesting story about a bird. Lola puts the book on a desk and draws a picture. A university student visits the library and helps her read a difficult word. The student says that pictures can help us understand a story. Lola thanks the student and continues reading.","sentences":["Lola finds a book in the library.","The book is about animals in Uzbekistan.","There is an interesting story about a bird.","Lola puts the book on a desk and draws a picture.","A university student visits the library and helps her read a difficult word.","The student says that pictures can help us understand a story.","Lola thanks the student and continues reading."],"questions":[{"id":"en-a1-04-reading0","type":"choice","skill":"reading","prompt":"Kitob nima haqida?","answers":["animals"],"explanation":"About animals mavzuni aytadi.","hint":"I have a book. The book is about animals. / an apple, a university","options":["animals","computers","sports"]},{"id":"en-a1-04-reading1","type":"choice","skill":"reading","prompt":"Kim Lola bilan ishlaydi?","answers":["a university student"],"explanation":"A university student deb yordamchi tanishtirilgan.","hint":"I have a book. The book is about animals. / an apple, a university","options":["a university student","a doctor","her brother"]},{"id":"en-a1-04-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"I have a book. The book is about animals. / an apple, a university","options":["Lola finds a book in the library.","The book is about animals in Uzbekistan.","There is an interesting story about a bird.","Lola puts the book on a desk and draws a picture.","A university student visits the library and helps her read a difficult word.","The student says that pictures can help us understand a story.","Lola thanks the student and continues reading."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I have a book and an apple in my bag. The book is about birds. The apple is green. I am going to the library after lunch.","audio":"/english-course/v7.23/en-a1-04.mp3","synthetic":true,"questions":[{"id":"en-a1-04-listening0","type":"choice","skill":"listening","prompt":"Kitob mavzusi nima?","answers":["birds"],"explanation":"The book is about birds deyiladi.","hint":"I have a book. The book is about animals. / an apple, a university","options":["birds","cars","flowers"]},{"id":"en-a1-04-listening1","type":"choice","skill":"listening","prompt":"Olma qanday rang?","answers":["green"],"explanation":"The apple is green deyiladi.","hint":"I have a book. The book is about animals. / an apple, a university","options":["green","red","yellow"]},{"id":"en-a1-04-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["birds","green"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"I have a book. The book is about animals. / an apple, a university","rows":["Kitob mavzusi","Olma rangi"]},{"id":"en-a1-04-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["He is a university student."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"I have a book. The book is about animals. / an apple, a university","audio":"/english-course/v7.23/en-a1-04-dictation.mp3","transcript":"He is a university student."}]},"writing":{"task":"Sumkangizdagi ikkita buyumni tanishtiring va keyin aynan shu buyumlarni tasvirlang.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I have a notebook and an apple in my bag. The notebook is blue, and the apple is green. I write new words in the notebook. I eat the apple after our English lesson.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I have a book.","The book is about animals.","She eats an apple."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Bir buyumni a/an bilan tanishtiring. Sherigingiz undan keyin the bilan savol bersin.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Sumkangizdagi ikkita buyumni tanishtiring va keyin aynan shu buyumlarni tasvirlang.","exit":[[{"id":"en-a1-04-exit0","type":"grammarFill","skill":"grammar","prompt":"___ interesting story","answers":["an"],"explanation":"A yoki an birinchi marta 