insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-05','en-a1-05',null,1,5,'published',1,'{"id":"en-a1-05","baseId":"en-a1-05","revision":1,"level":"A1","levelIndex":1,"order":5,"title":"Birlik va ko‘plik; this va these","objective":"Bir yoki bir nechta narsani yaqin va uzoqdan ko‘rsatasiz.","context":"O‘quvchilar kitob va qutilarni javonga joylaydi.","prerequisites":["en-a1-04"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Ko‘p sanaladigan otlarda ko‘plik -s, ayrimlarida -es bilan yasaladi: books, boxes. Child → children, man → men kabi istisnolarni alohida o‘rganamiz.","This/that birlik, these/those ko‘plik uchun ishlatiladi. This/these yaqin, that/those uzoqdagi narsani ko‘rsatadi.","These books are new — ko‘plik uchun are. This book is new — birlik uchun is. Demonstrative va fe’l bir-biriga mos bo‘lsin."],"pattern":"this book / these books; that box / those boxes","examples":["This book is new.","These books are new.","That box is heavy.","Those boxes are empty.","Two children are here.","These are my pens."],"vocabulary":[{"id":"en-a1-05-v0","term":"box","meaning":"quti","ipa":"/bɒks/","collocation":"an empty box","example":"That box is heavy."},{"id":"en-a1-05-v1","term":"heavy","meaning":"og‘ir","ipa":"/ˈhevi/","collocation":"a heavy bag","example":"That box is heavy."},{"id":"en-a1-05-v2","term":"empty","meaning":"bo‘sh","ipa":"/ˈempti/","collocation":"an empty box","example":"Those boxes are empty."},{"id":"en-a1-05-v3","term":"children","meaning":"bolalar","ipa":"/ˈtʃɪldrən/","collocation":"two children","example":"Two children are here."}],"visuals":[{"kind":"preposition","title":"Ma’no va tuzilish","items":["this book / these books; that box / those boxes","This book is new.","These books are new."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["O‘quvchilar kitob va qutilarni javonga joylaydi.","That box is heavy.","Two children are here."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Those boxes are empty.","audio":"/english-course/v7.23/en-a1-05-dictation.mp3"},"exercises":[{"id":"en-a1-05-choice","type":"choice","skill":"grammar","prompt":"Yaqindagi bir nechta ruchkani ko‘rsating.","answers":["These are pens."],"explanation":"These yaqin ko‘plik.","hint":"this book / these books; that box / those boxes","options":["These are pens.","This are pens.","Those is pen."]},{"id":"en-a1-05-gap","type":"grammarFill","skill":"grammar","prompt":"This book ___ new.","answers":["is"],"explanation":"Ko‘p sanaladigan otlarda ko‘plik -s, ayrimlarida -es bilan yasaladi: books, boxes. Child → children, man → men kabi istisnolarni alohida o‘rganamiz. This/that birlik, these/those ko‘plik uchun ishlatiladi. This/these yaqin, that/those uzoqdagi narsani ko‘rsatadi. These books are new — ko‘plik uchun are. This book is new — birlik uchun is. Demonstrative va fe’l bir-biriga mos bo‘lsin.","hint":"this book / these books; that box / those boxes"},{"id":"en-a1-05-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["This book is new."],"explanation":"Ko‘p sanaladigan otlarda ko‘plik -s, ayrimlarida -es bilan yasaladi: books, boxes. Child → children, man → men kabi istisnolarni alohida o‘rganamiz. This/that birlik, these/those ko‘plik uchun ishlatiladi. This/these yaqin, that/those uzoqdagi narsani ko‘rsatadi. These books are new — ko‘plik uchun are. This book is new — birlik uchun is. Demonstrative va fe’l bir-biriga mos bo‘lsin.","hint":"this book / these books; that box / those boxes","tokens":["This","book","is","new."]},{"id":"en-a1-05-fix","type":"correction","skill":"grammar","prompt":"These book is new.","answers":["These books are new."],"explanation":"Ko‘p sanaladigan otlarda ko‘plik -s, ayrimlarida -es bilan yasaladi: books, boxes. Child → children, man → men kabi istisnolarni alohida o‘rganamiz. This/that birlik, these/those ko‘plik uchun ishlatiladi. This/these yaqin, that/those uzoqdagi narsani ko‘rsatadi. These books are new — ko‘plik uchun are. This book is new — birlik uchun is. Demonstrative va fe’l bir-biriga mos bo‘lsin.","hint":"this book / these books; that box / those boxes"},{"id":"en-a1-05-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["quti","og‘ir","bo‘sh","bolalar"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"this book / these books; that box / those boxes","left":["box","heavy","empty","children"],"options":["quti","og‘ir","bo‘sh","bolalar"]}],"reading":{"title":"Birlik va ko‘plik; this va these — vaziyat","text":"This book is new, and these two books are old. Lola puts them on the small shelf. That box near the door is heavy because it has many notebooks inside. Those boxes by the window are empty. Two children help the teacher carry the books. They do not carry the heavy box alone. The teacher asks them to count all the pens on the desk.","sentences":["This book is new, and these two books are old.","Lola puts them on the small shelf.","That box near the door is heavy because it has many notebooks inside.","Those boxes by the window are empty.","Two children help the teacher carry the books.","They do not carry the heavy box alone.","The teacher asks them to count all the pens on the desk."],"questions":[{"id":"en-a1-05-reading0","type":"choice","skill":"reading","prompt":"Eshik yonidagi quti qanday?","answers":["heavy"],"explanation":"That box near the door is heavy.","hint":"this book / these books; that box / those boxes","options":["heavy","empty","small"]},{"id":"en-a1-05-reading1","type":"choice","skill":"reading","prompt":"Deraza yonidagi qutilar qanday?","answers":["empty"],"explanation":"Those boxes by the window are empty.","hint":"this book / these books; that box / those boxes","options":["empty","full","new"]},{"id":"en-a1-05-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"this book / these books; that box / those boxes","options":["This book is new, and these two books are old.","Lola puts them on the small shelf.","That box near the door is heavy because it has many notebooks inside.","Those boxes by the window are empty.","Two children help the teacher carry the books.","They do not carry the heavy box alone.","The teacher asks them to count all the pens on the desk."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"These are my pens. This is my notebook. Those boxes near the window are empty. There are two children next to the door. Please give them these books.","audio":"/english-course/v7.23/en-a1-05.mp3","synthetic":true,"questions":[{"id":"en-a1-05-listening0","type":"choice","skill":"listening","prompt":"Uzoqdagi qutilar qayerda?","answers":["near the window"],"explanation":"Those boxes near the window deyiladi.","hint":"this book / these books; that box / those boxes","options":["near the window","on the desk","under a bed"]},{"id":"en-a1-05-listening1","type":"choice","skill":"listening","prompt":"Nechta bola bor?","answers":["two"],"explanation":"Two children — istisno ko‘plik.","hint":"this book / these books; that box / those boxes","options":["two","three","four"]},{"id":"en-a1-05-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["two","boxes"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"this book / these books; that box / those boxes","rows":["Bolalar soni","Deraza yonidagi narsalar"]},{"id":"en-a1-05-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Those boxes are empty."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"this book / these books; that box / those boxes","audio":"/english-course/v7.23/en-a1-05-dictation.mp3","transcript":"Those boxes are empty."}]},"writing":{"task":"Xonadagi yaqin va uzoq buyumlarni to‘rtta gapda ko‘rsating. Birlik va ko‘plikni ishlating.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"This notebook is mine. These pens are on my desk. That box near the door is heavy. Those books on the high shelf are old. Two children help our teacher put the books away.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["This book is new.","These books are new.","That box is heavy."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Yaqindagi va uzoqdagi buyumlarni ko‘rsatib this/that/these/those bilan gapiring.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Xonadagi yaqin va uzoq buyumlarni to‘rtta gapda ko‘rsating. Birlik va ko‘plikni ishlating.","exit":[[{"id":"en-a1-05-exit0","type":"grammarFill","skill":"grammar","prompt":"One child, two ___.","answers":["children"],"explanation":"Ko‘p sanaladigan otlarda ko‘plik -s, a