insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-06','en-a1-06',null,1,6,'published',1,'{"id":"en-a1-06","baseId":"en-a1-06","revision":1,"level":"A1","levelIndex":1,"order":6,"title":"Egalik: my, your va ’s","objective":"Buyum yoki qarindoshlik kimga tegishli ekanini aytasiz.","context":"Mashg‘ulotdan keyin o‘quvchilar aralashib ketgan sumkalarni topadi.","prerequisites":["en-a1-05"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas.","Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags.","It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings."],"pattern":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","examples":["This is my bag.","Lola’s notebook is blue.","His father is a teacher.","Our classroom is bright.","The students’ bags are here.","The bird opens its wings."],"vocabulary":[{"id":"en-a1-06-v0","term":"father","meaning":"ota","ipa":"/ˈfɑːðə/","collocation":"my father","example":"His father is a teacher."},{"id":"en-a1-06-v1","term":"bright","meaning":"yorug‘","ipa":"/braɪt/","collocation":"a bright room","example":"Our classroom is bright."},{"id":"en-a1-06-v2","term":"wing","meaning":"qanot","ipa":"/wɪŋ/","collocation":"open its wings","example":"The bird opens its wings."},{"id":"en-a1-06-v3","term":"belong","meaning":"tegishli bo‘lmoq","ipa":"/bɪˈlɒŋ/","collocation":"belong to Lola","example":"belong to Lola"}],"visuals":[{"kind":"family","title":"Ma’no va tuzilish","items":["Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","This is my bag.","Lola’s notebook is blue."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Mashg‘ulotdan keyin o‘quvchilar aralashib ketgan sumkalarni topadi.","His father is a teacher.","The students’ bags are here."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Our classroom is bright.","audio":"/english-course/v7.23/en-a1-06-dictation.mp3"},"exercises":[{"id":"en-a1-06-choice","type":"choice","skill":"grammar","prompt":"Ali ning daftarini qanday aytamiz?","answers":["Ali’s notebook"],"explanation":"Ismga ’s qo‘shiladi.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["Ali’s notebook","Ali notebook’s","Alis notebook"]},{"id":"en-a1-06-gap","type":"grammarFill","skill":"grammar","prompt":"Lola has a bag. ___ bag is blue.","answers":["Her"],"explanation":"My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas. Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags. It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue"},{"id":"en-a1-06-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["This is my bag."],"explanation":"My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas. Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags. It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","tokens":["This","is","my","bag."]},{"id":"en-a1-06-fix","type":"correction","skill":"grammar","prompt":"The bird opens it’s wings.","answers":["The bird opens its wings."],"explanation":"My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas. Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags. It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue"},{"id":"en-a1-06-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["ota","yorug‘","qanot","tegishli bo‘lmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","left":["father","bright","wing","belong"],"options":["ota","yorug‘","qanot","tegishli bo‘lmoq"]},{"id":"en-a1-06-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["father","bright","wing","belong"],"options":["my father","a bright room","open its wings","belong to Lola"],"answers":["my father","a bright room","open its wings","belong to Lola"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Egalik: my, your va ’s — vaziyat","text":"Three bags are on the classroom floor. Lola’s bag is blue. Ali’s bag is black. Their teacher has a small brown bag. The students look inside their own bags and check their notebooks. Our classroom is bright, so finding the right colour is easy. A picture of a bird is on Lola’s bag. The bird opens its wings in the picture.","sentences":["Three bags are on the classroom floor.","Lola’s bag is blue.","Ali’s bag is black.","Their teacher has a small brown bag.","The students look inside their own bags and check their notebooks.","Our classroom is bright, so finding the right colour is easy.","A picture of a bird is on Lola’s bag.","The bird opens its wings in the picture."],"questions":[{"id":"en-a1-06-reading0","type":"choice","skill":"reading","prompt":"Ko‘k sumka kimniki?","answers":["Lola’s"],"explanation":"Lola’s bag is blue — egalik bevosita aytilgan.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["Lola’s","Ali’s","the teacher’s"]},{"id":"en-a1-06-reading1","type":"choice","skill":"reading","prompt":"O‘qituvchining sumkasi qanday rang?","answers":["brown"],"explanation":"Small brown bag o‘qituvchiga tegishli.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["brown","black","blue"]},{"id":"en-a1-06-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["Three bags are on the classroom floor.","Lola’s bag is blue.","Ali’s bag is black.","Their teacher has a small brown bag.","The students look inside their own bags and check their notebooks.","Our classroom is bright, so finding the right colour is easy.","A picture of a bird is on Lola’s bag.","The bird opens its wings in the picture."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"This is Lola’s notebook. Her name is inside. That is Ali’s pen. His pen is black. Our teacher’s bag is brown. Please give everyone their own things.","audio":"/english-course/v7.23/en-a1-06.mp3","synthetic":true,"questions":[{"id":"en-a1-06-listening0","type":"choice","skill":"listening","prompt":"Lolaning ismi qayerda?","answers":["inside the notebook"],"explanation":"Her name is inside deyiladi.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["inside the notebook","on the door","under a chair"]},{"id":"en-a1-06-listening1","type":"choice","skill":"listening","prompt":"Alining ruchkasi qanday rang?","answers":["black"],"explanation":"His pen is black.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["black","blue","brown"]},{"id":"en-a1-06-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["black","brown"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","rows":["Ali ruchkasining rangi","Ustoz sumkasining rangi"]},{"id":"en-a1-06-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Our classroom is bright."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","audio":"/english-course/v7.23/en-a1-06-dictation.mp3","transcript":"Our classroom is bright."}]},"writing":{"task":"Oiladagi yoki sinfdagi uch kishining buyumlarini egalik shakllari bilan tasvirlang.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"This is my brother’s notebook. His notebook is green. Lola’s bag is next to it, and her bag is blue. Our teacher’s pen is on the desk. We put everyone’s things in the right place.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["This is my bag.","Lola’s notebook is blue.","His father is a teacher."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Whose bag is this? savoliga ism va egalik sifati bilan javob bering.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Oiladagi yoki sinfdagi uch kishining buyumlarini egalik shakllari bilan tasvirlang.","exit":[[{"id":"en-a1-06-exit0","type":"grammarFill","skill":"grammar","prompt":"Lola’s bag = ___ bag.","answers":["her"],"explanation":"My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas. Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags. It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue"},{"id":"en-a1-06-exit1","type":"grammarFill","skill":"grammar","prompt":"We have a classroom. ___ classroom is bright.","answers":["Our"],"explanation":"My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas. Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags. It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue"},{"id":"en-a1-06-exit2","type":"grammarFill","skill":"grammar","prompt":"The bird opens ___ wings.","answers":["its"],"explanation":"My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas. Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags. It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue"},{"id":"en-a1-06-exit3","type":"choice","skill":"grammar","prompt":"It’s blue nimani anglatadi?","answers":["It is blue."],"explanation":"It’s bu yerda it is qisqartmasi.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["It is blue.","Its is blue.","It owns blue."]},{"id":"en-a1-06-exit4","type":"choice","skill":"grammar","prompt":"Ko‘plik egalikni tanlang.","answers":["the students’ bags"],"explanation":"Bir nechta student egada apostrof -s dan keyin.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["the students’ bags","the student’s bags (many owners)","the students bag"]}],[{"id":"en-a1-06-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Lola’s notebook is blue."],"explanation":"My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas. Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags. It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","tokens":["Lola’s","notebook","is","blue."]},{"id":"en-a1-06-exit-b1","type":"grammarFill","skill":"grammar","prompt":"We have a classroom. ___ classroom is bright.","answers":["Our"],"explanation":"My, your, his, her, its, our, their otdan oldin keladi: her bag. His erkak egaga, her ayol egaga bog‘liq; buyumning o‘z jinsiga emas. Ismga ’s qo‘shish egalikni bildiradi: Lola’s bag. Ko‘plik -s bilan tugasa, apostrof keyin keladi: the students’ bags. It’s — it is yoki it has qisqartmasi. Its esa apostrofsiz egalik shakli: The bird opens its wings.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue"},{"id":"en-a1-06-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers"