ences are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-08','en-a1-08',null,1,8,'published',1,'{"id":"en-a1-08","baseId":"en-a1-08","revision":1,"level":"A1","levelIndex":1,"order":8,"title":"There is va there are: xona xaritasi","objective":"Joyda nima borligini aytasiz va yo‘qligini tekshirasiz.","context":"Yangi kutubxona xonasi boshqalarga tanishtiriladi.","prerequisites":["en-a1-07"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["There is birlik yoki sanalmaydigan ot bilan, there are ko‘plik bilan ishlatiladi. Gap narsaning mavjudligini tanishtiradi.","Savolda is/are oldinga chiqadi: Is there a table? Are there chairs? Inkor: There isn’t …; There aren’t … .","It is a table buyumning nima ekanini aytadi. There is a table esa bu joyda stol borligini aytadi."],"pattern":"There is a desk. / There are four chairs. / Is there …?","examples":["There is a desk near the window.","There are four chairs.","Is there a clock?","There isn’t a computer.","Are there any books?","There are two shelves."],"vocabulary":[{"id":"en-a1-08-v0","term":"desk","meaning":"yozuv stoli","ipa":"/desk/","collocation":"near the desk","example":"There is a desk near the window."},{"id":"en-a1-08-v1","term":"shelf","meaning":"javon tokchasi","ipa":"/ʃelf/","collocation":"two shelves","example":"two shelves"},{"id":"en-a1-08-v2","term":"window","meaning":"deraza","ipa":"/ˈwɪndəʊ/","collocation":"near the window","example":"There is a desk near the window."},{"id":"en-a1-08-v3","term":"clock","meaning":"soat","ipa":"/klɒk/","collocation":"a wall clock","example":"Is there a clock?"}],"visuals":[{"kind":"room","title":"Ma’no va tuzilish","items":["There is a desk. / There are four chairs. / Is there …?","There is a desk near the window.","There are four chairs."]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Yangi kutubxona xonasi boshqalarga tanishtiriladi.","Is there a clock?","Are there any books?"]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"There isn’t a computer.","audio":"/english-course/v7.23/en-a1-08-dictation.mp3"},"exercises":[{"id":"en-a1-08-choice","type":"choice","skill":"grammar","prompt":"Bir stol borligini ayting.","answers":["There is a desk."],"explanation":"Desk birlik.","hint":"There is a desk. / There are four chairs. / Is there …?","options":["There is a desk.","There are a desk.","It there desk."]},{"id":"en-a1-08-gap","type":"grammarFill","skill":"grammar","prompt":"There ___ four chairs.","answers":["are"],"explanation":"There is birlik yoki sanalmaydigan ot bilan, there are ko‘plik bilan ishlatiladi. Gap narsaning mavjudligini tanishtiradi. Savolda is/are oldinga chiqadi: Is there a table? Are there chairs? Inkor: There isn’t …; There aren’t … . It is a table buyumning nima ekanini aytadi. There is a table esa bu joyda stol borligini aytadi.","hint":"There is a desk. / There are four chairs. / Is there …?"},{"id":"en-a1-08-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["There is a desk near the window."],"explanation":"There is birlik yoki sanalmaydigan ot bilan, there are ko‘plik bilan ishlatiladi. Gap narsaning mavjudligini tanishtiradi. Savolda is/are oldinga chiqadi: Is there a table? Are there chairs? Inkor: There isn’t …; There aren’t … . It is a table buyumning nima ekanini aytadi. There is a table esa bu joyda stol borligini aytadi.","hint":"There is a desk. / There are four chairs. / Is there …?","tokens":["There","is","a","desk","near","the","window."]},{"id":"en-a1-08-fix","type":"correction","skill":"grammar","prompt":"There is two shelves.","answers":["There are two shelves."],"explanation":"There is birlik yoki sanalmaydigan ot bilan, there are ko‘plik bilan ishlatiladi. Gap narsaning mavjudligini tanishtiradi. Savolda is/are oldinga chiqadi: Is there a table? Are there chairs? Inkor: There isn’t …; There aren’t … . It is a table buyumning nima ekanini aytadi. There is a table esa bu joyda stol borligini aytadi.","hint":"There is a desk. / There are four chairs. / Is there …?"},{"id":"en-a1-08-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["yozuv stoli","javon tokchasi","deraza","soat"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"There is a desk. / There are four chairs. / Is there …?","left":["desk","shelf","window","clock"],"options":["yozuv stoli","javon tokchasi","deraza","soat"]},{"id":"en-a1-08-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["There is a desk near the window."],"tokens":["There","is","a","desk","near","the","window."],"hint":"There is a desk. / There are four chairs. / Is there …?","explanation":"There is birlik yoki sanalmaydigan ot bilan, there are ko‘plik bilan ishlatiladi. Gap narsaning mavjudligini tanishtiradi."},{"id":"en-a1-08-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Birlik va ko‘plik; this va these: Yaqindagi bir nechta ruchkani ko‘rsating.","answers":["These are pens."],"explanation":"These yaqin ko‘plik.","hint":"this book / these books; that box / those boxes","options":["These are pens.","This are pens.","Those is pen."],"recap":true,"sourceLesson":"Birlik va ko‘plik; this va these"},{"id":"en-a1-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Egalik: my, your va ’s: Ali ning daftarini qanday aytamiz?","answers":["Ali’s notebook"],"explanation":"Ismga ’s qo‘shiladi.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["Ali’s notebook","Ali notebook’s","Alis notebook"],"recap":true,"sourceLesson":"Egalik: my, your va ’s"},{"id":"en-a1-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Have va has: oila va buyumlar: They ___ two books.","answers":["have"],"explanation":"They bilan have keladi.","hint":"I have … / She has … / Does she have …? / She doesn’t have …","options":["have","has","is"],"recap":true,"sourceLesson":"Have va has: oila va buyumlar"}],"reading":{"title":"There is va there are: xona xaritasi — vaziyat","text":"Our new reading room is small but bright. There is a desk near the window. There are four chairs around it. There are two shelves on the wall and many books on them. There is a clock above the door. There isn’t a computer in this room. Students use the computer room next door when they need to search for information.","sentences":["Our new reading room is small but bright.","There is a desk near the window.","There are four chairs around it.","There are two shelves on the wall and many books on them.","There is a clock above the door.","There isn’t a computer in this room.","Students use the computer room next door when they need to search for information."],"questions":[{"id":"en-a1-08-reading0","type":"choice","skill":"reading","prompt":"Xonada nechta stul bor?","answers":["four"],"explanation":"There are four chairs.","hint":"There is a desk. / There are four chairs. / Is there …?","options":["four","two","six"]},{"id":"en-a1-08-reading1","type":"choice","skill":"reading","prompt":"Xonada kompyuter bormi?","answers":["No"],"explanation":"There isn’t a computer.","hint":"There is a desk. / There are four chairs. / Is there …?","options":["No","Yes","There are two"]},{"id":"en-a1-08-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"There is a desk. / There are four chairs. / Is there …?","options":["Our new reading room is small but bright.","There is a desk near the window.","There are four chairs around it.","There are two shelves on the wall and many books on them.","There is a clock above the door.","There isn’t a computer in this room.","Students use the computer room next door when they need to search for information."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"Welcome to the reading room. There is a desk near the window. There are four chairs and two shelves. There is no computer here. The computer room is next door.","audio":"/english-course/v7.23/en-a1-08.mp3","synthetic":true,"questions":[{"id":"en-a1-08-listening0","type":"choice","skill":"listening","prompt":"Tokchalar soni qancha?","answers":["two"],"explanation":"Two shelves deyiladi.","hint":"There is a desk. / There are four chairs. / Is there …?","options":["two","four","one"]},{"id":"en-a1-08-listening1","type":"choice","skill":"listening","prompt":"Kompyuter xonasi qayerda?","answers":["next door"],"explanation":"The computer room is next door.","hint":"There is a desk. / There are four chairs. / Is there …?","options":["next door","upstairs","outside"]},{"id":"en-a1-08-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["four","two"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"There is a desk. / There are four chairs. / Is there …?","rows":["Stullar","Tokchalar"]},{"id":"en-a1-08-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["There isn’t a computer."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"There is a desk. / There are four chairs. / Is there …?","audio":"/english-course/v7.23/en-a1-08-dictation.mp3","transcript":"There isn’t a computer."}]},"writing":{"task":"Xonangizning kichik xaritasini tasvirlang: kamida uch bor va bir yo‘q narsa.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"There is a small desk near my window. There are two chairs and three shelves in my room. There is a lamp on the desk. There isn’t a television. I read and do homework in this quiet room.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["There is a desk near the window.","There are four chairs.","Is there a clock?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Xona xaritasini tasvirlang; sherigingiz Is there …? bilan tekshirsin.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Xonangizning kichik xaritasini tasvirlang: kamida uch bor va bir yo‘q narsa.","exit":[[{"id":"en-a1-08-exit0","type":"grammarFill","skill":"grammar","prompt":"There ___ a clock.","answers":["is"],"explanation":"There is birlik yoki sanalmaydigan ot bilan, there are ko‘plik bilan ishlatiladi. Gap narsaning mavjudligini tanishtiradi. Savolda is/are oldinga chiqadi: Is there a table? Are there chairs? Inkor: There isn’t …; There aren’t … . It is a table buyumning nima ekanini aytadi. There is a table esa bu joyda stol borligini aytadi.","hint":"There is a desk. / There are four chairs. / Is there …?"},{"id":"en-a1-08-exit1","type":"grammarFill","skill":"grammar","prompt":"___ there four chairs?","answers":["Are"],"explanation":"There is birlik yoki sanalmaydi