p":true,"sourceLesson":"Birlik va ko‘plik; this va these"},{"id":"en-a1-08-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Egalik: my, your va ’s: Ali ning daftarini qanday aytamiz?","answers":["Ali’s notebook"],"explanation":"Ismga ’s qo‘shiladi.","hint":"Lola’s bag = her bag; our classroom; its colour ≠ it’s blue","options":["Ali’s notebook","Ali notebook’s","Alis notebook"],"recap":true,"sourceLesson":"Egalik: my, your va ’s"},{"id":"en-a1-08-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Have va has: oila va buyumlar: They ___ two books.","answers":["have"],"explanation":"They bilan have keladi.","hint":"I have … / She has … / Does she have …? / She doesn’t have …","options":["have","has","is"],"recap":true,"sourceLesson":"Have va has: oila va buyumlar"}]}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-a1-09','en-a1-09',null,1,9,'published',1,'{"id":"en-a1-09","baseId":"en-a1-09","revision":1,"level":"A1","levelIndex":1,"order":9,"title":"Present Simple: odatlar va kun tartibi","objective":"Takrorlanadigan ishlar haqida gapirasiz va he/she uchun fe’lni moslaysiz.","context":"Ali va Lola maktabga borish tartibini solishtiradi.","prerequisites":["en-a1-08"],"minutes":25,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi.","Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays.","Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi."],"pattern":"I go / she goes; I study / he studies; every day","examples":["I walk to school every day.","She goes by bus.","Ali studies English after school.","We play football on Fridays.","My father works in a shop.","Lola reads before bed."],"vocabulary":[{"id":"en-a1-09-v0","term":"walk","meaning":"piyoda yurmoq","ipa":"/wɔːk/","collocation":"walk to school","example":"I walk to school every day."},{"id":"en-a1-09-v1","term":"every day","meaning":"har kuni","ipa":"/ˈevri deɪ/","collocation":"read every day","example":"I walk to school every day."},{"id":"en-a1-09-v2","term":"before","meaning":"oldin","ipa":"/bɪˈfɔː/","collocation":"before bed","example":"Lola reads before bed."},{"id":"en-a1-09-v3","term":"study","meaning":"o‘qimoq, o‘rganmoq","ipa":"/ˈstʌdi/","collocation":"study English","example":"study English"}],"visuals":[{"kind":"timeline","title":"Ma’no va tuzilish","items":["I go / she goes; I study / he studies; every day","I walk to school every day.","She goes by bus."],"timeline":[{"why":"Every day bir martalik hozirgi voqeani emas, takrorlanadigan odatni bildiradi.","events":[{"kind":"repeat","from":70,"to":570,"label":"Ko‘p kunlarda takrorlanadi"}]},{"why":"Goes uchinchi shaxs shakli; bu yerda avtobusdagi odatiy yo‘l aytilgan.","events":[{"kind":"repeat","from":70,"to":570,"label":"Odatiy yo‘l"}]}]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Ali va Lola maktabga borish tartibini solishtiradi.","Ali studies English after school.","My father works in a shop."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"We play football on Fridays.","audio":"/english-course/v7.23/en-a1-09-dictation.mp3"},"exercises":[{"id":"en-a1-09-choice","type":"choice","skill":"grammar","prompt":"He ___ in a shop.","answers":["works"],"explanation":"He uchun fe’lga -s qo‘shiladi.","hint":"I go / she goes; I study / he studies; every day","options":["works","work","working"]},{"id":"en-a1-09-gap","type":"grammarFill","skill":"grammar","prompt":"She ___ to school by bus. (go)","answers":["goes"],"explanation":"Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi. Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays. Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi.","hint":"I go / she goes; I study / he studies; every day"},{"id":"en-a1-09-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["I walk to school every day."],"explanation":"Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi. Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays. Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi.","hint":"I go / she goes; I study / he studies; every day","tokens":["I","walk","to","school","every","day."]},{"id":"en-a1-09-fix","type":"correction","skill":"grammar","prompt":"Ali study English.","answers":["Ali studies English."],"explanation":"Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi. Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays. Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi.","hint":"I go / she goes; I study / he studies; every day"},{"id":"en-a1-09-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["piyoda yurmoq","har kuni","oldin","o‘qimoq, o‘rganmoq"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"I go / she goes; I study / he studies; every day","left":["walk","every day","before","study"],"options":["piyoda yurmoq","har kuni","oldin","o‘qimoq, o‘rganmoq"]},{"id":"en-a1-09-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["walk","every day","before","study"],"options":["walk to school","read every day","before bed","study English"],"answers":["walk to school","read every day","before bed","study English"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Present Simple: odatlar va kun tartibi — vaziyat","text":"Ali walks to school every day. His sister goes by bus because her school is far from home. After school, Ali studies English for twenty minutes. On Fridays, he plays football with friends. Lola reads before bed and writes new words in a notebook. Both students enjoy their lessons, but they have different daily routines. At the weekend, they often meet in the park.","sentences":["Ali walks to school every day.","His sister goes by bus because her school is far from home.","After school, Ali studies English for twenty minutes.","On Fridays, he plays football with friends.","Lola reads before bed and writes new words in a notebook.","Both students enjoy their lessons, but they have different daily routines.","At the weekend, they often meet in the park."],"questions":[{"id":"en-a1-09-reading0","type":"choice","skill":"reading","prompt":"Ali maktabga qanday boradi?","answers":["on foot"],"explanation":"Walks piyoda borishni bildiradi.","hint":"I go / she goes; I study / he studies; every day","options":["on foot","by bus","by car"]},{"id":"en-a1-09-reading1","type":"choice","skill":"reading","prompt":"Lola qachon o‘qiydi?","answers":["before bed"],"explanation":"Reads before bed — uxlash oldidan.","hint":"I go / she goes; I study / he studies; every day","options":["before bed","on the bus","during lunch"]},{"id":"en-a1-09-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"I go / she goes; I study / he studies; every day","options":["Ali walks to school every day.","His sister goes by bus because her school is far from home.","After school, Ali studies English for twenty minutes.","On Fridays, he plays football with friends.","Lola reads before bed and writes new words in a notebook.","Both students enjoy their lessons, but they have different daily routines.","At the weekend, they often meet in the park."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"I walk to school every day. My sister goes by bus. After school, I study English for twenty minutes. On Fridays, I play football. Lola reads before bed.","audio":"/english-course/v7.23/en-a1-09.mp3","synthetic":true,"questions":[{"id":"en-a1-09-listening0","type":"choice","skill":"listening","prompt":"Ingliz tili uchun qancha vaqt ajratiladi?","answers":["twenty minutes"],"explanation":"Twenty minutes deyiladi.","hint":"I go / she goes; I study / he studies; every day","options":["twenty minutes","ten minutes","thirty minutes"]},{"id":"en-a1-09-listening1","type":"choice","skill":"listening","prompt":"Futbol qachon?","answers":["on Fridays"],"explanation":"On Fridays aniq aytilgan.","hint":"I go / she goes; I study / he studies; every day","options":["on Fridays","on Mondays","every morning"]},{"id":"en-a1-09-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["twenty minutes","Fridays"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"I go / she goes; I study / he studies; every day","rows":["O‘qish vaqti","Futbol kuni"]},{"id":"en-a1-09-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We play football on Fridays."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"I go / she goes; I study / he studies; every day","audio":"/english-course/v7.23/en-a1-09-dictation.mp3","transcript":"We play football on Fridays."}]},"writing":{"task":"Kun tartibingiz va oila a’zongizning odatlarini solishtiring.","audience":"Sinfdagi sherigingiz","minWords":30,"maxWords":90,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I walk to school every morning. My brother goes by bus. After school, I study English and do homework. He plays football with friends. We eat dinner together, and I read a short story before bed.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["I walk to school every day.","She goes by bus.","Ali studies English after school."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Kundalik uch odatingizni ayting. Keyin sherigingizning odatini he yoki she bilan qayta ayting.","seconds":35,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Kun tartibingiz va oila a’zongizning odatlarini solishtiring.","exit":[[{"id":"en-a1-09-exit0","type":"grammarFill","skill":"grammar","prompt":"She ___ before bed. (read)","answers":["reads"],"explanation":"Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi. Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays. Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi.","hint":"I go / she goes; I study / he studies; every day"},{"id":"en-a1-09-exit1","type":"grammarFill","skill":"grammar","prompt":"He ___ English. (study)","answers":["studies"],"explanation":"Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi. Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays. Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi.","hint":"I go / she goes; I study / he studies; every day"},{"id":"en-a1-09-exit2","type":"grammarFill","skill":"grammar","prompt":"I ___ to school. (walk)","answers":["walk"],"explanation":"Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi. Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays. Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi.","hint":"I go / she goes; I study / he studies; every day"},{"id":"en-a1-09-exit3","type":"choice","skill":"grammar","prompt":"Takroriy odatni tanlang.","answers":["She reads every day."],"explanation":"Every day muntazam takrorni bildiradi.","hint":"I go / she goes; I study / he studies; every day","options":["She reads every day.","She is reading now.","She read yesterday."]},{"id":"en-a1-09-exit4","type":"choice","skill":"grammar","prompt":"Go ning he uchun shakli qaysi?","answers":["goes"],"explanation":"Go → goes.","hint":"I go / she goes; I study / he studies; every day","options":["goes","gos","go"]}],[{"id":"en-a1-09-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["She goes by bus."],"explanation":"Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi. Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays. Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi.","hint":"I go / she goes; I study / he studies; every day","tokens":["She","goes","by","bus."]},{"id":"en-a1-09-exit-b1","type":"grammarFill","skill":"grammar","prompt":"He ___ English. (study)","answers":["studies"],"explanation":"Present Simple odat, takror va umumiy holatni bildiradi. I walk; he walks. He/she/it da odatda -s yoki -es qo‘shiladi. Go → goes, study → studies. Undosh+y bilan tugagan fe’lda y o‘rniga -ies, lekin play → plays. Doimiy odat now dagi ayni davom etayotgan ish bilan bir xil emas. Every day, on Mondays kabi belgilar takrorni ko‘rsatadi.","hint":"I go / she goes; I study / he studies; every day"},{"id":"